import{_ as t,o as a,c as s,al as i}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"PX4 시스템 콘솔","description":"","frontmatter":{},"headers":[],"relativePath":"ko/debug/system_console.md","filePath":"ko/debug/system_console.md"}'),d={name:"ko/debug/system_console.md"};function o(r,e,n,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="px4-시스템-콘솔" tabindex="-1">PX4 시스템 콘솔 <a class="header-anchor" href="#px4-시스템-콘솔" aria-label="Permalink to &quot;PX4 시스템 콘솔&quot;">​</a></h1><p>The PX4 <em>System Console</em> provides low-level access to the system, debug output and analysis of the system boot process.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The console should be used for debugging if the system won&#39;t boot. The <a href="./../debug/mavlink_shell">MAVLink Shell</a> may otherwise be more suitable, as it is much easier to set up and can be used for <a href="./../debug/consoles#console_vs_shell">many of the same tasks</a>.</p></div><h2 id="콘솔-배선" tabindex="-1">콘솔 배선 <a class="header-anchor" href="#콘솔-배선" aria-label="Permalink to &quot;콘솔 배선&quot;">​</a></h2><p>The console is made available through a (board-specific) UART that can be connected to a computer USB port using a <a href="https://www.digikey.com/en/products/detail/TTL-232R-3V3/768-1015-ND/1836393" target="_blank" rel="noreferrer">3.3V FTDI</a> cable. 이렇게 하면, 터미널 응용 프로그램을 사용하여 콘솔에 접근할 수 있습니다.</p><p>Pixhawk controller manufacturers are expected to expose the console UART and SWD (JTAG) debug interfaces through a dedicated <em>debug port</em> that complies with the <a href="#pixhawk_debug_port">Pixhawk Connector Standard</a>. 불행히도, 일부 보드는 이 표준 이전이거나 비준수품입니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Developers targeting a number of different boards may wish to use a <a href="./../debug/swd_debug#debug-adapters">debug adapter</a> to simplify connecting boards to FTDI cables and <a href="./../debug/swd_debug#debug-probes-for-px4-hardware">debug probes</a>.</p></div><p>아래 섹션은 많은 공통 보드에 대한 배선 및 시스템 콘솔 정보에 대한 개요를 설명합니다.</p><h3 id="보드별-연결-방법" tabindex="-1">보드별 연결 방법 <a class="header-anchor" href="#보드별-연결-방법" aria-label="Permalink to &quot;보드별 연결 방법&quot;">​</a></h3><p>The System Console UART pinouts/debug ports are typically documented in the affected <a href="./../flight_controller/">autopilot overview pages</a>. For example, see <a href="./../flight_controller/mro_pixhawk#console-port">mRo Pixhawk</a> and <a href="./../flight_controller/pixracer#debug-port">Pixracer</a>.</p><h3 id="pixhawk_debug_port" tabindex="-1">Pixhawk Debug Port <a class="header-anchor" href="#pixhawk_debug_port" aria-label="Permalink to &quot;Pixhawk Debug Port {#pixhawk_debug_port}&quot;">​</a></h3><p>Pixhawk flight controllers usually come with a <a href="./../debug/swd_debug#pixhawk-connector-standard-debug-ports">Pixhawk Connector Standard Debug Port</a> which will be either the 10 pin <a href="./../debug/swd_debug#pixhawk-debug-full">Pixhawk Debug Full</a> or 6 pin <a href="./../debug/swd_debug#pixhawk-debug-mini">Pixhawk Debug Mini</a> port.</p><p>These ports have pins for console TX and RX which can connect to an FTDI cable. The mapping for the <a href="./../debug/swd_debug#pixhawk-debug-mini">Pixhawk Debug Mini</a> to FTDI is shown below.</p><table tabindex="0"><thead><tr><th>Pixhawk 디버그 포트</th><th>-</th><th>FTDI</th><th>-</th></tr></thead><tbody><tr><td>1(red)</td><td>TARGET PROCESSOR VOLTAGE</td><td></td><td>N/C (SWD/JTAG 디버깅에 사용됨)</td></tr><tr><td>2 (흑)</td><td>CONSOLE TX (출력)</td><td>5</td><td>FTDI RX (황)</td></tr><tr><td>3 (흑)</td><td>CONSOLE RX (입력)</td><td>4</td><td>FTDI TX (적황)</td></tr><tr><td>4 (흑)</td><td>SWDIO</td><td></td><td>N/C (SWD/JTAG 디버깅에 사용됨)</td></tr><tr><td>5 (흑)</td><td>SWCLK</td><td></td><td>N/C (SWD/JTAG 디버깅에 사용됨)</td></tr><tr><td>6 (흑)</td><td>GND</td><td>1</td><td>FTDI GND (흑)</td></tr></tbody></table><p>The <a href="./../debug/swd_debug">SWD Debug Port</a> page and individual flight controller pages have more information about debug port pinouts.</p><h2 id="콘솔-열기" tabindex="-1">콘솔 열기 <a class="header-anchor" href="#콘솔-열기" aria-label="Permalink to &quot;콘솔 열기&quot;">​</a></h2><p>콘솔 연결이 연결된 후, 선택한 기본 직렬 포트 도구 또는 아래에 설명된 기본값을 사용합니다.</p><h3 id="linux-mac-운영체제-screen" tabindex="-1">Linux / Mac 운영체제: Screen <a class="header-anchor" href="#linux-mac-운영체제-screen" aria-label="Permalink to &quot;Linux / Mac 운영체제: Screen&quot;">​</a></h3><p>Ubuntu에 screen 명령어를 설치합니다. Mac OS에 이미 설치되어 있습니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> screen</span></span></code></pre></div><ul><li>시리얼: Pixhawk v1 / Pixracer는 57600 보드를 사용합니다.</li></ul><p>Connect screen at BAUDRATE baud, 8 data bits, 1 stop bit to the right serial port (use <code>ls /dev/tty*</code> and watch what changes when unplugging / replugging the USB device). Common names are <code>/dev/ttyUSB0</code> and <code>/dev/ttyACM0</code> for Linux and <code>/dev/tty.usbserial-ABCBD</code> for Mac OS.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyXXX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BAUDRATE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8N1</span></span></code></pre></div><h3 id="윈도우-putty" tabindex="-1">윈도우: PuTTY <a class="header-anchor" href="#윈도우-putty" aria-label="Permalink to &quot;윈도우: PuTTY&quot;">​</a></h3><p>Download <a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html" target="_blank" rel="noreferrer">PuTTY</a> and start it.</p><p>&#39;직렬 연결&#39;을 선택하고, 포트 매개변수를 다음과 같이 설정합니다.</p><ul><li>초당 전송속도: 57600</li><li>8 data bits</li><li>1 stop bit</li></ul>',27)])])}const b=t(d,[["render",o]]);export{u as __pageData,b as default};
